import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 28 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Passages lean toward economics, social
 * science, and classic & modern literature, and are distinct from other forms.
 */

// ─────────────────────── PRACTICE TEST 28 · R&W M1 (27) ──────────────────────
const T28_RW_M1: SatQuestion[] = [
  { id: "t28rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The merchant kept his ledgers in such ______ order that an auditor could trace any single coin across a decade of trade.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["impeccable", "tentative", "negligent", "casual"], correct: 0, explanation: "Tracing any coin across a decade requires flawless, \"impeccable\" record-keeping. Tentative and casual imply hesitation or informality, and negligent means careless, all of which contradict the precision described." },
  { id: "t28rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee ______ its final report only after every member had reviewed the draft.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["submit", "submits", "submitted", "have submitted"], correct: 2, explanation: "The sentence describes a completed past action signaled by \"only after every member had reviewed,\" so the simple past \"submitted\" agrees in time. \"Submit\" and \"submits\" are present tense, and \"have submitted\" is plural and present-perfect, wrong for a singular subject and a finished past event." },
  { id: "t28rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Economist Elinor Ostrom challenged the idea that shared resources like fisheries are doomed to overuse. Studying communities worldwide, she showed that groups often craft their own rules to manage commons sustainably without state or private ownership.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Ostrom found that communities can self-govern shared resources sustainably, contrary to the assumption they must collapse.", "Ostrom proved that only governments can protect fisheries.", "Ostrom concluded that all shared resources inevitably collapse.", "Ostrom studied a single fishery and made no broader claims."], correct: 0, explanation: "The text says she \"challenged\" the doom assumption and showed groups craft sustainable rules, which choice A captures. B and C state positions she opposed, and D contradicts \"communities worldwide.\"" },
  { id: "t28rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup missed its first revenue target by a wide margin. ______, investors withdrew their funding within the quarter.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "Consequently", "However", "Similarly"], correct: 1, explanation: "Withdrawing funding is the result of missing the target, a cause-effect link signaled by \"Consequently.\" Nonetheless and However signal contrast, and Similarly signals comparison, none of which fit a result." },
  { id: "t28rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The anthropologist studied three communities ______ a fishing village, a mountain hamlet, and a desert outpost.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["communities, ", "communities: ", "communities; ", "communities "], correct: 1, explanation: "A colon properly introduces the list that names the \"three communities.\" A comma is too weak for a full appositive list, a semicolon must join independent clauses, and no punctuation leaves the list unmarked." },
  { id: "t28rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although the manor in the novel appears grand, the narrator's spare descriptions make its halls feel ______, as if no warmth had ever lingered there.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["desolate", "festive", "cozy", "bustling"], correct: 0, explanation: "Halls with no warmth that ever lingered are \"desolate.\" Festive, cozy, and bustling all suggest liveliness or comfort, the opposite of the bleak image the spare descriptions create." },
  { id: "t28rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A tax credit applies only to households that earn below $50,000 annually and that file jointly.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A household earning $40,000 that files separately would not receive the credit.", "Any household that files jointly receives the credit.", "Income alone determines eligibility.", "The credit ignores filing status."], correct: 0, explanation: "Both conditions are required, so a household that files separately fails the joint-filing rule, as choice A states. B and C ignore the dual requirement, and D contradicts the stated filing condition." },
  { id: "t28rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The city expanded its bus routes into outer neighborhoods. ______, it added late-night service on the busiest lines.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Adding late-night service is a further expansion stacked onto the new routes, signaled by \"In addition.\" However and Instead imply contrast or replacement, and Otherwise implies a consequence, none of which fit an added measure." },
  { id: "t28rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Critics called the playwright's dialogue ______: each line revealed character so efficiently that no word felt wasted.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economical", "verbose", "muddled", "redundant"], correct: 0, explanation: "Revealing character with no wasted word describes \"economical\" dialogue. Verbose and redundant mean wordy or repetitive, and muddled means confused, all contradicting the efficiency praised." },
  { id: "t28rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Researchers tracking household savings found that families given automatic enrollment in retirement plans saved far more than families asked to opt in voluntarily, even though both groups could leave the plan at any time.", prompt: "Which finding from the text best supports the claim that default settings shape behavior?", type: "mcq", choices: ["Automatically enrolled families saved more despite being free to leave the plan.", "Both groups could leave the plan at any time.", "The families were all asked about retirement.", "Voluntary enrollment was offered to one group."], correct: 0, explanation: "The claim is about defaults shaping behavior; the higher savings of auto-enrolled families who could still leave isolates the default as the cause, which choice A states. B, C, and D describe shared conditions that do not show the default's effect." },
  { id: "t28rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the recovered manuscripts ______ a clue about the lost city's trade networks.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["offer", "offers", "are offering", "have offered"], correct: 1, explanation: "\"Each\" is singular and governs the verb, so the singular \"offers\" agrees. The plural \"offer,\" \"are offering,\" and \"have offered\" are misled by the nearby plural \"manuscripts,\" which is only the object of the preposition." },
  { id: "t28rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The author wanted to emphasize that the reform was modest. Which choice most effectively makes that point?", prompt: "Which choice most effectively achieves the author's goal?", type: "mcq", choices: ["The reform raised the wage by a mere fifteen cents an hour.", "The reform transformed the entire labor market overnight.", "The reform was the most sweeping in the nation's history.", "The reform affected millions of workers immediately."], correct: 0, explanation: "A \"mere fifteen cents\" stresses how small the change was, matching the goal of emphasizing modesty. The other choices describe a large, sweeping, or far-reaching reform, the opposite of modest." },
  { id: "t28rw1-13", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "In Charlotte Brontë's Villette, the narrator Lucy Snowe often withholds her own feelings from the reader, describing events in clinical detail while concealing the storm beneath.", prompt: "As used in the text, \"clinical\" most nearly means", type: "mcq", choices: ["detached", "medical", "experimental", "sterile"], correct: 0, explanation: "Describing events while \"concealing the storm beneath\" frames \"clinical\" as emotionally \"detached.\" The medical and experimental senses ignore the context of hidden feeling, and sterile, though related, refers to lifelessness rather than the deliberate restraint described." },
  { id: "t28rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The negotiators reached an agreement ______ it took three sleepless nights to draft the terms.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["agreement, although", "agreement although", "agreement; although", "agreement: although"], correct: 0, explanation: "A comma correctly attaches the dependent clause beginning with \"although\" to the main clause. Omitting the comma runs the clauses together, and a semicolon or colon must follow an independent clause, not introduce a subordinate one." },
  { id: "t28rw1-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A survey of remote workers found that those who kept a fixed morning routine reported sharper focus throughout the day than those whose schedules varied widely.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Remote workers with consistent morning routines reported better focus than those without them.", "Remote work always reduces focus.", "Morning routines have no effect on workers.", "All remote workers keep fixed routines."], correct: 0, explanation: "The survey links a fixed routine to sharper focus, which choice A restates. B overgeneralizes, C contradicts the finding, and D misreads the comparison between two groups." },
  { id: "t28rw1-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory cut its energy use by half. ______, its monthly costs dropped sharply.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "In contrast", "Even so", "Meanwhile"], correct: 0, explanation: "Falling costs follow from cutting energy use, a result signaled by \"As a result.\" In contrast and Even so signal opposition, and Meanwhile signals simultaneity without causation." },
  { id: "t28rw1-17", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The diplomat's reply was deliberately ______, leaving both sides free to interpret it as a small victory.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "blunt", "precise", "hostile"], correct: 0, explanation: "Wording that lets both sides read it differently is \"ambiguous.\" Blunt and precise imply clear, single meanings, and hostile contradicts the conciliatory aim of letting each side claim a victory." },
  { id: "t28rw1-18", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The economist, ______ argued that inflation would ease, was later proven right.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["who", "whom", "which", "whose"], correct: 0, explanation: "The relative pronoun is the subject of \"argued,\" so the subject form \"who\" is correct and refers to a person. \"Whom\" is the object form, \"which\" is for things, and \"whose\" shows possession." },
  { id: "t28rw1-19", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Sociologists studying neighborhood trust found that blocks with frequent informal gatherings reported lower crime than demographically similar blocks without them, suggesting that social ties, not just policing, shape safety.", prompt: "Which choice best describes the function of the underlined phrase \"demographically similar\" in the text?", type: "mcq", choices: ["It controls for outside factors so the difference can be attributed to social ties.", "It shows the blocks had different populations.", "It proves policing is irrelevant.", "It introduces an unrelated comparison."], correct: 0, explanation: "Matching blocks on demographics rules out population differences, letting the gatherings explain the gap, which choice A states. B reverses the meaning of \"similar,\" C overstates the modest claim, and D misreads a controlled comparison as unrelated." },
  { id: "t28rw1-20", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The poet revised the stanza six times. ______, she felt it still lacked the right rhythm.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Even so", "Likewise", "Thus"], correct: 1, explanation: "Despite six revisions the stanza still fell short, a contrast signaled by \"Even so.\" Therefore and Thus signal a result, and Likewise signals similarity, none of which fit the unexpected shortfall." },
  { id: "t28rw1-21", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The historian's account is admirably ______: she weighs the testimony of rulers and peasants alike before drawing any conclusion.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["evenhanded", "biased", "careless", "dismissive"], correct: 0, explanation: "Weighing all testimony before concluding is \"evenhanded.\" Biased and dismissive imply favoring or ignoring one side, and careless contradicts the deliberate weighing described." },
  { id: "t28rw1-22", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew loaded the supplies, secured the rigging, and ______ before dawn.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["setting sail", "set sail", "had set sail", "to set sail"], correct: 1, explanation: "The list of past-tense actions \"loaded,\" \"secured,\" and \"set sail\" must stay parallel, so \"set sail\" matches. The participle, past-perfect, and infinitive forms all break the parallel structure of the series." },
  { id: "t28rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The labor report shows that wages in the technology sector rose 6 percent last year, while wages in manufacturing rose only 1 percent over the same period.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["Technology wages grew faster than manufacturing wages last year.", "Manufacturing wages fell last year.", "Both sectors grew at the same rate.", "Technology wages did not change."], correct: 0, explanation: "Six percent exceeds one percent, so technology wages grew faster, as choice A states. B contradicts the 1 percent rise, C ignores the gap between the figures, and D contradicts the 6 percent increase." },
  { id: "t28rw1-24", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Text 1 argues that the gig economy frees workers to set their own hours and choose their own clients. Text 2 counters that this freedom is illusory, since platform algorithms quietly dictate when and how much workers must labor to earn a living.", prompt: "How would the author of Text 2 most likely respond to the claim in Text 1?", type: "mcq", choices: ["By contending that the apparent freedom is constrained by hidden algorithmic pressures.", "By agreeing that gig workers enjoy total independence.", "By denying that algorithms exist on these platforms.", "By praising the gig economy for eliminating all schedules."], correct: 0, explanation: "Text 2 calls the freedom \"illusory\" because algorithms \"dictate\" the work, so its author would stress hidden constraints, as choice A says. B and D restate Text 1's view, and C contradicts Text 2's own premise about algorithms." },
  { id: "t28rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "While researching the essay, the student gathered these notes: The cooperative was founded in 1844. It began with twenty-eight members. It sold goods at fair prices. It returned profits to members as dividends.", prompt: "The student wants to emphasize how the cooperative shared its earnings. Which choice most effectively uses the notes to accomplish this goal?", type: "mcq", choices: ["Founded in 1844, the cooperative returned its profits to members as dividends.", "The cooperative was founded in 1844 with twenty-eight members.", "The cooperative began with twenty-eight members and sold goods.", "The cooperative, founded in 1844, sold goods at fair prices."], correct: 0, explanation: "Returning profits as dividends directly emphasizes how earnings were shared, fulfilling the goal. The other choices focus on the founding date, membership, or pricing and never mention sharing earnings." },
  { id: "t28rw1-26", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive's oldest map, ______ ink had faded to a pale brown, was carefully restored.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["whose", "who's", "that", "which"], correct: 0, explanation: "The possessive relative pronoun \"whose\" correctly shows the ink belongs to the map. \"Who's\" means \"who is,\" and \"that\" and \"which\" cannot show possession of the ink." },
  { id: "t28rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In Gabriel García Márquez's One Hundred Years of Solitude, events recur across generations with eerie similarity, as if the family were trapped in a loop it cannot perceive from within.", prompt: "Which choice best states the central idea of the text?", type: "mcq", choices: ["The novel portrays a family caught in repeating patterns it fails to recognize.", "The novel follows a single character over one year.", "The novel rejects any sense of repetition.", "The novel praises the family for escaping its past."], correct: 0, explanation: "Recurring events and a loop the family \"cannot perceive\" describe repeating, unrecognized patterns, as choice A states. B misstates the multigenerational scope, C contradicts the recurrence, and D contradicts the family being trapped." },
];

// ─────────────────── PRACTICE TEST 28 · R&W M2 EASIER (27) ───────────────────
const T28_RW_M2E: SatQuestion[] = [
  { id: "t28rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new café was so ______ that customers lined up before it even opened each morning.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["popular", "empty", "hidden", "unknown"], correct: 0, explanation: "Long morning lines mean the café was \"popular.\" Empty, hidden, and unknown all suggest few customers, contradicting the crowds described." },
  { id: "t28rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The two friends ______ to the library after school.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["walks", "walk", "walking", "to walk"], correct: 1, explanation: "The plural subject \"two friends\" takes the plural verb \"walk.\" \"Walks\" is singular, and \"walking\" and \"to walk\" are not finite main verbs for the sentence." },
  { id: "t28rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Honeybees communicate the location of flowers by performing a looping \"waggle dance\" inside the hive.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees use a dance to share where flowers are.", "Bees cannot find flowers.", "Bees sing to one another.", "Bees avoid the hive."], correct: 0, explanation: "The text says the waggle dance communicates flower locations, which choice A states. B contradicts the dance's purpose, C invents singing, and D contradicts dancing inside the hive." },
  { id: "t28rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The team practiced every day for a month. ______, they won the championship.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Instead", "In contrast"], correct: 1, explanation: "Winning follows from the practice, a result signaled by \"As a result.\" However, Instead, and In contrast all signal opposition or substitution, which the cause-effect link does not call for." },
  { id: "t28rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The store sells three kinds of bread ______ rye, wheat, and sourdough.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["bread, ", "bread: ", "bread; ", "bread "], correct: 1, explanation: "A colon introduces the list naming the \"three kinds of bread.\" A comma is too weak for the full list, a semicolon needs independent clauses, and no punctuation leaves the list unmarked." },
  { id: "t28rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the travelers were ______ and could barely climb the last hill.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["exhausted", "energetic", "cheerful", "rested"], correct: 0, explanation: "Barely able to climb means the travelers were \"exhausted.\" Energetic, cheerful, and rested all suggest the opposite of fatigue." },
  { id: "t28rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The recipe calls for two cups of flour and one cup of sugar.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The recipe uses more flour than sugar.", "The recipe uses no flour.", "The recipe uses equal flour and sugar.", "The recipe uses more sugar than flour."], correct: 0, explanation: "Two cups of flour exceeds one cup of sugar, so choice A is supported. B contradicts the flour amount, C ignores the difference, and D reverses the quantities." },
  { id: "t28rw2e-8", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The library added new computers. ______, it extended its weekend hours.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Instead", "In addition", "However", "Otherwise"], correct: 1, explanation: "Extending hours is another improvement added to the computers, signaled by \"In addition.\" Instead and However imply replacement or contrast, and Otherwise implies a consequence." },
  { id: "t28rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were so ______ that no one in the class got lost on the way to the museum.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["clear", "confusing", "secret", "wrong"], correct: 0, explanation: "If no one got lost, the directions were \"clear.\" Confusing, secret, and wrong would all lead people astray, contradicting the result." },
  { id: "t28rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and ______ planted a garden behind the house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["me", "I", "myself", "mine"], correct: 1, explanation: "The pronoun is part of the compound subject, so the subject form \"I\" is correct. \"Me\" is an object form, \"myself\" is reflexive, and \"mine\" is possessive." },
  { id: "t28rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Penguins keep warm in icy water thanks to a thick layer of fat beneath their feathers.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A layer of fat helps penguins stay warm.", "Penguins cannot swim.", "Penguins have no feathers.", "Penguins live in deserts."], correct: 0, explanation: "The text says fat keeps penguins warm, as choice A states. B, C, and D contradict swimming, feathers, and the icy setting mentioned." },
  { id: "t28rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The author wants to stress that the trip was short. Which choice best does this?", prompt: "Which choice most effectively achieves the author's goal?", type: "mcq", choices: ["The visit lasted barely two hours.", "The visit stretched across many weeks.", "The visit covered the entire summer.", "The visit was the longest of the year."], correct: 0, explanation: "\"Barely two hours\" stresses how short the trip was. The other choices describe long stretches of time, the opposite of short." },
  { id: "t28rw2e-13", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puppy was ______ and wagged its tail at every visitor who came to the door.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["friendly", "fierce", "shy", "silent"], correct: 0, explanation: "Wagging its tail at every visitor shows the puppy was \"friendly.\" Fierce, shy, and silent contradict the welcoming behavior." },
  { id: "t28rw2e-14", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The chef chopped the vegetables ______ she heated the pan.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["while", "while,", "while;", "while:"], correct: 0, explanation: "The subordinating conjunction \"while\" joins the clauses without added punctuation. Adding a comma, semicolon, or colon after \"while\" wrongly breaks the conjunction from its clause." },
  { id: "t28rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The schedule shows that the bus arrives at 8:00 and the train arrives at 8:15.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The bus arrives before the train.", "The train arrives first.", "Both arrive at the same time.", "Neither arrives in the morning."], correct: 0, explanation: "8:00 comes before 8:15, so the bus arrives first, as choice A states. B reverses the order, C ignores the difference, and D contradicts the morning times." },
  { id: "t28rw2e-16", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It started to rain heavily. ______, the picnic was moved indoors.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Instead", "Likewise"], correct: 0, explanation: "Moving indoors results from the rain, signaled by \"Therefore.\" However and Instead signal contrast or substitution, and Likewise signals similarity." },
  { id: "t28rw2e-17", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The scientist's explanation was ______, so even beginners understood the experiment right away.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["simple", "complicated", "vague", "lengthy"], correct: 0, explanation: "If beginners understood right away, the explanation was \"simple.\" Complicated, vague, and lengthy would make understanding harder, contradicting the result." },
  { id: "t28rw2e-18", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The runners ______ tired after the race, but they smiled anyway.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "being"], correct: 1, explanation: "The plural subject \"runners\" takes the plural past verb \"were.\" \"Was\" and \"is\" are singular, and \"being\" is not a finite verb." },
  { id: "t28rw2e-19", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Maps from the ancient city show wide roads leading to a central marketplace, suggesting trade was important to its people.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The city's layout suggests trade mattered to its people.", "The city had no roads.", "The city avoided all trade.", "The city had no marketplace."], correct: 0, explanation: "Roads leading to a marketplace point to the importance of trade, as choice A states. B, C, and D contradict the roads, trade, and marketplace described." },
  { id: "t28rw2e-20", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The bakery sold out of muffins early. ______, it baked a second batch by noon.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "Instead", "Nevertheless"], correct: 1, explanation: "Baking more is a response to selling out, a result signaled by \"So.\" However, Instead, and Nevertheless all signal contrast, which does not fit the logical follow-up." },
  { id: "t28rw2e-21", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The old bridge was ______, and engineers warned that it could not safely carry heavy trucks.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["fragile", "sturdy", "modern", "wide"], correct: 0, explanation: "A bridge that cannot carry heavy trucks is \"fragile.\" Sturdy and modern suggest strength, and wide describes size, none matching the safety warning." },
  { id: "t28rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The painter cleaned her brushes ______ stored them in a wooden box.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["and", "and,", "but", "or"], correct: 0, explanation: "\"And\" joins the two related actions of cleaning and storing. A comma after \"and\" is unneeded, \"but\" implies contrast, and \"or\" implies an alternative." },
  { id: "t28rw2e-23", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The chart shows that the town's population grew from 5,000 in 2000 to 8,000 in 2020.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The town's population increased over those twenty years.", "The town's population fell.", "The population stayed the same.", "The town had no residents in 2000."], correct: 0, explanation: "8,000 is greater than 5,000, so the population increased, as choice A states. B and C contradict the growth, and D contradicts the 5,000 figure for 2000." },
  { id: "t28rw2e-24", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The garden needed water. ______, the gardener turned on the sprinklers.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["So", "However", "Instead", "Although"], correct: 0, explanation: "Turning on sprinklers responds to the need for water, a result signaled by \"So.\" However and Instead signal contrast, and \"Although\" cannot stand alone as a transition here." },
  { id: "t28rw2e-25", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lecture was ______, and many students struggled to stay awake.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dull", "exciting", "brief", "loud"], correct: 0, explanation: "Students struggling to stay awake means the lecture was \"dull.\" Exciting contradicts the boredom, and brief and loud do not explain drowsiness." },
  { id: "t28rw2e-26", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Neither the coach nor the players ______ ready for the surprise drill.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "In a \"neither...nor\" pair, the verb agrees with the nearer subject, the plural \"players,\" so \"were\" is correct. \"Was,\" \"is,\" and \"has been\" are singular and do not match the closer plural noun." },
  { id: "t28rw2e-27", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "In the short story, the lighthouse keeper waves to every passing ship, hoping someone will one day stop to talk with him.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The keeper longs for company.", "The keeper dislikes ships.", "The keeper hides from sailors.", "The keeper never sees any ships."], correct: 0, explanation: "Hoping someone will stop to talk shows the keeper \"longs for company,\" as choice A states. B, C, and D contradict the friendly waving and his hope for contact." },
];

// ─────────────────── PRACTICE TEST 28 · R&W M2 HARDER (27) ───────────────────
const T28_RW_M2H: SatQuestion[] = [
  { id: "t28rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "In Herman Melville's Bartleby, the Scrivener, the narrator's repeated insistence that he is an \"eminently safe man\" reads less as fact than as a defense he keeps mounting against his own creeping unease.", prompt: "Which choice best describes the function of the phrase \"eminently safe man\" as the narrator uses it?", type: "mcq", choices: ["It reveals self-reassurance that masks the narrator's growing disquiet.", "It objectively reports the narrator's personality.", "It mocks Bartleby's recklessness.", "It introduces a new minor character."], correct: 0, explanation: "The text says the claim \"reads less as fact than as a defense\" against \"creeping unease,\" so it masks disquiet, as choice A states. B takes it at face value, C misattributes it to Bartleby, and D invents a new character." },
  { id: "t28rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Behavioral economists distinguish between stated preferences, what people say they value, and revealed preferences, what their actual choices show they value. The two frequently diverge, which is why surveys alone often mispredict markets.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["What people say they value often differs from what their choices reveal, limiting surveys.", "Surveys always predict markets accurately.", "Stated and revealed preferences are identical.", "People never reveal their preferences through choices."], correct: 0, explanation: "The text says the two preferences \"frequently diverge,\" making surveys unreliable, as choice A states. B and C contradict that divergence, and D contradicts the very definition of revealed preferences." },
  { id: "t28rw2h-3", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The treaty, signed by delegates from twelve nations, ______ within a year because no enforcement body existed to uphold its terms.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["collapse", "collapses", "collapsed", "collapsing"], correct: 2, explanation: "The phrase \"within a year\" with the past-tense reason clause requires the singular past verb \"collapsed\" for the singular subject \"treaty.\" \"Collapse\" and \"collapses\" are present tense, and \"collapsing\" is not a finite main verb." },
  { id: "t28rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The firm doubled its advertising budget last spring. ______, sales in the following quarter remained flat, prompting a rethink of the strategy.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Accordingly", "Yet", "Hence", "Thus"], correct: 1, explanation: "Flat sales despite a doubled budget is an unexpected contrast signaled by \"Yet.\" Accordingly, Hence, and Thus all signal a result, which would wrongly imply the spending paid off." },
  { id: "t28rw2h-5", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Text 1 claims that minimum-wage increases reduce employment by raising the cost of hiring. Text 2 reports studies of neighboring counties where one raised its wage and the other did not, finding no measurable job loss in the higher-wage county.", prompt: "How does Text 2 most directly challenge Text 1?", type: "mcq", choices: ["By offering empirical evidence that a wage increase did not reduce employment.", "By agreeing that wage increases always cut jobs.", "By arguing that wages should never rise.", "By ignoring employment data entirely."], correct: 0, explanation: "Text 2's county comparison shows no job loss, directly testing Text 1's prediction, as choice A states. B and C misstate Text 2's position, and D contradicts its use of employment data." },
  { id: "t28rw2h-6", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study of urban migration found that newcomers who joined local community organizations within their first year reported a stronger sense of belonging a decade later than newcomers who did not, even after accounting for income and education.", prompt: "Which finding best supports the claim that early civic participation fosters long-term belonging?", type: "mcq", choices: ["Newcomers who joined organizations early reported more belonging ten years later, controlling for income and education.", "All newcomers reported the same sense of belonging.", "The study tracked newcomers for only one month.", "Income fully explained the differences in belonging."], correct: 0, explanation: "Controlling for income and education isolates early participation as the factor tied to later belonging, as choice A states. B contradicts the difference found, C misstates the decade-long span, and D contradicts the control for income." },
  { id: "t28rw2h-7", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The curator arranged the relics chronologically; ______ visitors could trace the empire's rise and fall in a single walk.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["as a result,", "as a result", "however,", "nevertheless"], correct: 0, explanation: "After the semicolon, the conjunctive adverb \"as a result\" needs a following comma and signals the cause-effect link to the chronological arrangement. Omitting the comma is incorrect punctuation, and \"however\" and \"nevertheless\" wrongly signal contrast." },
  { id: "t28rw2h-8", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "As used in this passage from a treatise on civic life, \"ferment\" describes a society whose ideas are in constant agitation, churning toward something new.", prompt: "As used in the text, \"ferment\" most nearly means", type: "mcq", choices: ["upheaval", "decay", "stillness", "fatigue"], correct: 0, explanation: "Ideas in \"constant agitation\" churning toward the new point to \"upheaval.\" Decay and fatigue suggest decline, and stillness is the opposite of agitation." },
  { id: "t28rw2h-9", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Anthropologist Marcel Mauss argued that in many societies gift-giving is never truly free: each gift creates an obligation to reciprocate, weaving a web of mutual debt that binds the community together.", prompt: "Which choice best states the central claim of the text?", type: "mcq", choices: ["Gifts create reciprocal obligations that bind a community together.", "Gifts are always given without any expectation.", "Gift-giving weakens social bonds.", "Mauss studied only economic transactions."], correct: 0, explanation: "The text says gifts create an \"obligation to reciprocate\" that binds the community, as choice A states. B contradicts \"never truly free,\" C reverses the binding effect, and D ignores the social, not purely economic, focus." },
  { id: "t28rw2h-10", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The novelist drafted the entire manuscript by hand. ______, she insisted on retyping each page herself rather than hiring an assistant.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Moreover", "Otherwise", "Instead"], correct: 1, explanation: "Retyping each page herself adds to her hands-on method, an additive link signaled by \"Moreover.\" By contrast and Instead imply opposition, and Otherwise implies a consequence, none fitting the reinforcing detail." },
  { id: "t28rw2h-11", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The economist's prose is admirably ______: she states each premise plainly, leaving no hidden assumption for the reader to uncover.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["transparent", "obscure", "florid", "evasive"], correct: 0, explanation: "Stating premises plainly with no hidden assumption is \"transparent.\" Obscure and evasive imply concealment, and florid implies ornate excess, all contradicting the clarity praised." },
  { id: "t28rw2h-12", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The researchers published their findings, ______ had taken six years to gather, in a leading journal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["which", "that", "who", "what"], correct: 0, explanation: "The nonrestrictive clause set off by commas requires \"which\" to refer to the \"findings.\" \"That\" cannot follow a comma in a nonrestrictive clause, \"who\" is for people, and \"what\" cannot introduce this relative clause." },
  { id: "t28rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In Kazuo Ishiguro's The Remains of the Day, the butler Stevens recounts decades of devoted service in measured, formal prose, yet the reader gradually senses the regret he cannot bring himself to name.", prompt: "Which choice best describes the relationship between Stevens's prose and his feelings?", type: "mcq", choices: ["His controlled prose conceals an unspoken regret the reader perceives anyway.", "His prose openly celebrates his every choice.", "His prose has no emotional undercurrent.", "His prose directly states his regret in full."], correct: 0, explanation: "Measured prose paired with regret \"he cannot bring himself to name\" shows concealment the reader still senses, as choice A states. B and C deny the undercurrent, and D contradicts the regret being unspoken." },
  { id: "t28rw2h-14", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to underscore the unexpectedness of the discovery. Which choice best accomplishes this?", prompt: "Which choice most effectively achieves the author's goal?", type: "mcq", choices: ["The fossil surfaced not in a remote desert but in the gravel of a suburban driveway.", "The fossil was studied carefully by a team of experts.", "The fossil was about two meters in length.", "The fossil was placed in a museum case."], correct: 0, explanation: "Finding the fossil in a suburban driveway rather than a desert stresses how unexpected the discovery was. The other choices describe study, size, or display and convey nothing surprising." },
  { id: "t28rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Text 1 holds that automation will free workers from drudgery to pursue creative work. Text 2 cautions that without retraining programs, automation may instead leave displaced workers without any path back into the labor force.", prompt: "The author of Text 2 would most likely characterize the optimism in Text 1 as", type: "mcq", choices: ["incomplete, because it overlooks the need for retraining.", "fully justified and requiring no qualification.", "irrelevant to the question of employment.", "proof that automation harms no one."], correct: 0, explanation: "Text 2 warns the benefit depends on retraining, so it would call Text 1's optimism \"incomplete,\" as choice A states. B ignores the caution, C denies the shared topic of employment, and D reverses Text 2's warning." },
  { id: "t28rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A long-term study found that regions adopting universal preschool saw higher high-school graduation rates two decades later than comparable regions without it, even among children whose families had not changed income.", prompt: "Which choice best supports the claim that preschool access, not family income, drove the later gains?", type: "mcq", choices: ["Graduation gains appeared even among children whose family income had not changed.", "The regions were studied for only one year.", "All children attended preschool.", "Family income rose sharply in every region."], correct: 0, explanation: "Gains appearing where income did not change isolates preschool as the driver, as choice A states. B misstates the two-decade span, C ignores the comparison regions, and D contradicts the unchanged income." },
  { id: "t28rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having reviewed the evidence for months, ______ before reaching a verdict.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["the jury deliberated carefully", "the verdict was reached carefully", "careful deliberation occurred", "it was deliberated carefully"], correct: 0, explanation: "The opening modifier \"Having reviewed the evidence\" must attach to the people who reviewed it, the jury, so \"the jury deliberated carefully\" avoids a dangling modifier. The other choices begin with a verdict or abstract noun that did not review the evidence." },
  { id: "t28rw2h-18", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The reformer's pamphlet was famously ______: its barbed phrasing spared neither allies nor opponents who failed to meet its standard.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["acerbic", "gentle", "flattering", "soothing"], correct: 0, explanation: "Barbed phrasing that spares no one is \"acerbic.\" Gentle, flattering, and soothing all suggest mildness or praise, the opposite of sharp criticism." },
  { id: "t28rw2h-19", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The data note shows that in the surveyed city, public-transit ridership rose 12 percent in years when fuel prices were high and fell 4 percent in years when fuel prices were low.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Transit ridership tended to rise when fuel prices were high.", "Transit ridership was unaffected by fuel prices.", "Ridership fell whenever fuel prices rose.", "Fuel prices never changed."], correct: 0, explanation: "Ridership rose 12 percent in high-fuel years, so it tended to rise with fuel prices, as choice A states. B ignores the correlation, C reverses it, and D contradicts the varying prices described." },
  { id: "t28rw2h-20", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The expedition reached the summit ahead of schedule. ______, a sudden storm forced the climbers to descend before they could plant their flag.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Even so", "Hence", "Accordingly"], correct: 1, explanation: "Descending without planting the flag undercuts the early arrival, a contrast signaled by \"Even so.\" Therefore, Hence, and Accordingly all signal a result, which the reversal does not fit." },
  { id: "t28rw2h-21", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "As used in a passage describing a fragile coalition, \"tenuous\" characterizes an alliance held together by little more than shared fear of a common rival.", prompt: "As used in the text, \"tenuous\" most nearly means", type: "mcq", choices: ["flimsy", "permanent", "official", "expanding"], correct: 0, explanation: "An alliance held by \"little more than\" shared fear is \"flimsy.\" Permanent and official imply strength or formality, and expanding implies growth, none matching the fragility described." },
  { id: "t28rw2h-22", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The investors were impressed by the founder's vision and ______ that the product could scale quickly.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["by her confidence", "her confidence", "she was confident", "being confident"], correct: 0, explanation: "Parallel structure requires the second item to match \"by the founder's vision,\" so \"by her confidence\" keeps the prepositional pattern. The other choices break the parallel \"by X and by Y\" construction." },
  { id: "t28rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Sociologists have observed that rituals marking life transitions, such as graduations and weddings, persist across cultures because they help communities collectively acknowledge and absorb change.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Transition rituals endure because they help communities process change together.", "Rituals are disappearing from all cultures.", "Rituals serve no social function.", "Only weddings count as rituals."], correct: 0, explanation: "The text says rituals persist because they help communities \"acknowledge and absorb change,\" as choice A states. B contradicts \"persist,\" C denies their function, and D ignores the broader examples given." },
  { id: "t28rw2h-24", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "While researching, a student compiled these notes: The guild formed in 1390. It set fixed prices for cloth. It trained apprentices for seven years. It fined members who broke its rules.", prompt: "The student wants to emphasize how the guild enforced its standards. Which choice best uses the notes to do this?", type: "mcq", choices: ["The guild fined members who broke its rules, enforcing its standards.", "The guild, formed in 1390, trained apprentices for seven years.", "The guild set fixed prices for cloth across the city.", "The guild was formed in 1390 by local weavers."], correct: 0, explanation: "Fining rule-breakers directly shows enforcement, fulfilling the goal. The other choices focus on the founding, apprenticeship, or pricing and do not address enforcement." },
  { id: "t28rw2h-25", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir's tone is strikingly ______: the author neither excuses her mistakes nor wallows in them, recounting each with steady candor.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unsentimental", "maudlin", "evasive", "boastful"], correct: 0, explanation: "Refusing both excuse and wallowing while recounting with candor is \"unsentimental.\" Maudlin means overly emotional, evasive means avoiding, and boastful means self-praising, all contradicting the steady candor." },
  { id: "t28rw2h-26", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The architect's boldest design, a glass tower that seemed to defy gravity, ______ never built because the city denied the permit.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "was", "are", "have been"], correct: 1, explanation: "The singular subject \"design\" governs the verb, so the singular \"was\" agrees despite the intervening appositive. \"Were,\" \"are,\" and \"have been\" are plural or present and do not match the singular past subject." },
  { id: "t28rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Text 1 argues that cities should ban cars from their centers to cut pollution. Text 2 acknowledges the environmental benefit but warns that, without affordable transit alternatives, such bans burden low-income workers who depend on driving.", prompt: "Which choice best captures the relationship between the two texts?", type: "mcq", choices: ["Text 2 accepts Text 1's goal but raises an equity concern about its method.", "Text 2 rejects Text 1's environmental premise entirely.", "Text 2 fully endorses Text 1 without reservation.", "Text 2 denies that pollution is a problem."], correct: 0, explanation: "Text 2 \"acknowledges the environmental benefit\" yet warns about burdening low-income workers, accepting the goal while raising an equity concern, as choice A states. B and D contradict the acknowledgment, and C ignores the warning." },
];

