const T28_M_M1: SatQuestion[] = [
  { id: "t28m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x − 7 = 21, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Add 7 to both sides: 4x = 28. Divide by 4: x = 7. Final answer: 7. A trap is dividing 21 by 4 before adding 7." },
  { id: "t28m1-2", section: "math", domain: "Algebra", difficulty: "med", prompt: "A phone plan costs $30 per month plus $0.10 per gigabyte of data. Which expression gives the monthly cost in dollars for g gigabytes?", type: "mcq", choices: ["30 + 0.10g", "30g + 0.10", "0.10 + 30g", "30 − 0.10g"], correct: 0, explanation: "Goal: model the cost. The flat fee 30 is added to 0.10 per gigabyte times g, giving 30 + 0.10g. Final answer: 30 + 0.10g. A trap is attaching the rate to the wrong term, as in 30g + 0.10." },
  { id: "t28m1-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A jacket originally priced at $80 is on sale for 25% off. What is the sale price, in dollars?", type: "grid", gridAnswers: ["60"], explanation: "Goal: find the sale price. A 25% discount keeps 75%: 0.75 × 80 = 60. Final answer: 60. A trap is subtracting 25 dollars instead of 25 percent, giving 55." },
  { id: "t28m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 6. What is its circumference? (Use C = 2πr.)", type: "mcq", choices: ["12π", "6π", "36π", "3π"], correct: 0, explanation: "Goal: find the circumference. Apply C = 2πr = 2π(6) = 12π. Final answer: 12π. A trap is using the area formula πr² = 36π instead." },
  { id: "t28m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = −2x + 9 passes through the point (3, k). What is the value of k?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the y-value at x = 3. Substitute: k = −2(3) + 9 = −6 + 9 = 3. Final answer: 3. A trap is ignoring the negative sign and getting 15." },
  { id: "t28m1-6", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the product of the solutions to x² − 7x + 12 = 0?", type: "grid", gridAnswers: ["12"], explanation: "Goal: find the product of the roots. Factor: (x − 3)(x − 4) = 0, so roots are 3 and 4, and 3 × 4 = 12 (which equals c/a). Final answer: 12. A trap is summing the roots to 7 instead." },
  { id: "t28m1-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a class of 30 students, the ratio of those who walk to school to those who ride the bus is 2:3. How many students ride the bus?", type: "grid", gridAnswers: ["18"], explanation: "Goal: find bus riders. The ratio has 2 + 3 = 5 parts for 30 students, so each part is 6. Bus riders are 3 parts: 3 × 6 = 18. Final answer: 18. A trap is reporting the 2-part walkers, 12." },
  { id: "t28m1-8", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 50° and 60°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["70"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°: 180 − 50 − 60 = 70. Final answer: 70. A trap is adding only the two given angles to get 110." },
  { id: "t28m1-9", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3(x + 2) = 27, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Divide both sides by 3: x + 2 = 9. Subtract 2: x = 7. Final answer: 7. A trap is subtracting 2 from 27 before dividing." },
  { id: "t28m1-10", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 2x² − 5, what is the value of f(3)?", type: "grid", gridAnswers: ["13"], explanation: "Goal: evaluate f at 3. Substitute: 2(3²) − 5 = 2(9) − 5 = 18 − 5 = 13. Final answer: 13. A trap is squaring after multiplying, computing (2·3)² = 36." },
  { id: "t28m1-11", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of five test scores is 84. What is the sum of the five scores?", type: "grid", gridAnswers: ["420"], explanation: "Goal: find the total. The sum equals the mean times the count: 84 × 5 = 420. Final answer: 420. A trap is dividing instead of multiplying." },
  { id: "t28m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x − 6)(x + 2) = x² + bx − 12, what is the value of b?", type: "grid", gridAnswers: ["-4"], explanation: "Goal: find b. Expand: x² + 2x − 6x − 12 = x² − 4x − 12, so b = −4. Final answer: −4. A trap is adding 6 and 2 to get 8 instead of combining −6 and +2." },
  { id: "t28m1-13", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (1, 4) and (5, 16) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use rise over run: (16 − 4)/(5 − 1) = 12/4 = 3. Final answer: 3. A trap is inverting to run over rise, giving 1/3." },
  { id: "t28m1-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has a length of 12 and a width of 5. What is the length of its diagonal?", type: "mcq", choices: ["13", "17", "7", "60"], correct: 0, explanation: "Goal: find the diagonal. By the Pythagorean theorem, d = √(12² + 5²) = √(144 + 25) = √169 = 13. Final answer: 13. A trap is adding the sides to get 17." },
  { id: "t28m1-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A car travels 150 miles in 3 hours at a constant speed. At this rate, how many miles does it travel in 5 hours?", type: "grid", gridAnswers: ["250"], explanation: "Goal: find distance in 5 hours. The speed is 150/3 = 50 mph, so 50 × 5 = 250 miles. Final answer: 250. A trap is adding 150 and 5 or scaling incorrectly." },
  { id: "t28m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^(x+1) = 32, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential. Write 32 as 2^5, so x + 1 = 5 and x = 4. Final answer: 4. A trap is solving x + 1 = 32 by ignoring the base." },
  { id: "t28m1-17", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 2y = 24 and y = 2, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Substitute y = 2: 5x + 4 = 24, so 5x = 20 and x = 4. Final answer: 4. A trap is forgetting to subtract the 4 before dividing." },
  { id: "t28m1-18", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 6x + 5 crosses the x-axis at two points. What is the larger x-intercept?", type: "grid", gridAnswers: ["5"], explanation: "Goal: find the larger root. Factor: (x − 1)(x − 5) = 0, giving x = 1 and x = 5; the larger is 5. Final answer: 5. A trap is reporting the smaller root 1." },
  { id: "t28m1-19", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe that serves 4 requires 6 cups of flour. How many cups are needed to serve 10 people?", type: "grid", gridAnswers: ["15"], explanation: "Goal: scale the recipe. Flour per person is 6/4 = 1.5 cups, so for 10 people: 1.5 × 10 = 15. Final answer: 15. A trap is adding 6 to the difference in servings." },
  { id: "t28m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has a leg of 9 and a hypotenuse of 15. What is the length of the other leg?", type: "grid", gridAnswers: ["12"], explanation: "Goal: find the missing leg. By the Pythagorean theorem, leg = √(15² − 9²) = √(225 − 81) = √144 = 12. Final answer: 12. A trap is adding instead of subtracting under the radical." },
  { id: "t28m1-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + 10x + k is a perfect square trinomial, what is the value of k?", type: "grid", gridAnswers: ["25"], explanation: "Goal: find k. A perfect square (x + a)² = x² + 2ax + a² needs 2a = 10, so a = 5 and k = a² = 25. Final answer: 25. A trap is using a = 5 directly as k." },
  { id: "t28m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $18 per hour and works 35 hours in a week. How much does the worker earn that week, in dollars?", type: "grid", gridAnswers: ["630"], explanation: "Goal: find total pay. Multiply rate by hours: 18 × 35 = 630. Final answer: 630. A trap is adding the two numbers or using a partial week." },
];

